import type { BootstrapConfig } from "./config.js";
import type { Auth0ProvisionResult } from "./provision.js";

export function buildEnvFile(
  config: BootstrapConfig,
  auth0: Auth0ProvisionResult | null,
): string {
  const lines: string[] = [
    "# Generated by auth0-livepeer bootstrap",
    "# Auth0 + OpenMeter + remote signer webhook + Collector",
    "",
  ];

  if (auth0) {
    lines.push(
      "# Auth0",
      `AUTH0_DOMAIN=${config.auth0Domain}`,
      `AUTH0_ISSUER=${auth0.issuer}`,
      `AUTH0_JWKS_URL=${auth0.jwksUrl}`,
      `AUTH0_AUDIENCE=${auth0.apiIdentifier}`,
      `AUTH0_PUBLIC_CLIENT_ID=${auth0.publicClientId}`,
      `AUTH0_M2M_CLIENT_ID=${auth0.m2mClientId}`,
      `AUTH0_M2M_CLIENT_SECRET=${auth0.m2mClientSecret}`,
      "",
      "# remote_signer_webhook (JWT validation)",
      `JWKS_URL=${auth0.jwksUrl}`,
      `JWT_ISSUER=${auth0.issuer}`,
      `JWT_AUDIENCE=${auth0.apiIdentifier}`,
      `WEBHOOK_SECRET=${config.webhookSecret}`,
      "CLAIM_CLIENT_ID=azp",
      "USAGE_SUBJECT_TYPE=auth0_user_id",
      "",
    );
  }

  if (!config.skipOpenMeter) {
    lines.push(
      "# OpenMeter",
      `OPENMETER_URL=${config.openmeterUrl.replace(/\/$/, "")}`,
    );
    if (config.openmeterApiKey) {
      lines.push(`OPENMETER_API_KEY=${config.openmeterApiKey}`);
    }
    lines.push(
      `OPENMETER_TRIAL_FEATURE_KEY=${config.trialFeatureKey}`,
      "",
    );
  }

  lines.push(
    "# builder-sdk hosted signer proxy",
    `SIGNER_PROXY_URL=${config.signerProxyUrl}`,
    "",
    "# Kafka (go-livepeer -monitor)",
    `KAFKA_BROKERS=${config.kafkaBrokers}`,
    `KAFKA_GATEWAY_TOPIC=${config.kafkaGatewayTopic}`,
    "",
    "# OpenMeter Collector (Wei -> USD micros)",
    `ETH_USD_PRICE=${config.ethUsdPrice}`,
    "",
    "# go-livepeer remote signer (example flags)",
    "# -remoteSigner",
    "# -monitor",
    `# -kafkaBootstrapServers ${config.kafkaBrokers}`,
    `# -kafkaGatewayTopic ${config.kafkaGatewayTopic}`,
    "# -remoteSignerUsageIdentityMode webhook",
    "# -remoteSignerWebhookUrl http://127.0.0.1:8090/authorize",
    `# -remoteSignerWebhookHeaders Authorization:Bearer ${config.webhookSecret}`,
    "",
    "# Start webhook: pnpm --dir builder-sdk webhook:serve (see @pymthouse/builder-sdk/signer/webhook)",
    "# Start collector: see config/openmeter-collector.yaml",
  );

  return lines.join("\n");
}
